/*
 * MQTT-Zugänge merken
 *
 * Die Oberfläche veröffentlicht auf pm/status/mqtt-zugaenge (retained,
 * QoS 1), welche Shellys bestätigt über ihren eigenen MQTT-Zugang
 * verbunden sind:
 *   { "ts": 1727200000000,
 *     "geschuetzt": { "kuehlhaus": "shelly/kuehlhaus",
 *                     "shelly1-b929cc": "shellies/shelly1-B929CC" } }
 * Schlüssel ist der Gerätename, wie ihn die Shelly-Funktionen bilden
 * (letztes Segment des Präfixes, klein), Wert das genaue Präfix des Geräts.
 * Ein leeres Objekt heißt: kein Gerät ist geschützt.
 *
 * Wozu: Den Baum <präfix>/# eines solchen Geräts sperrt der Broker für den
 * gemeinsamen Zugang „shelly". Den Gerätenamen leiten die Shelly-Funktionen
 * aber verlustbehaftet aus dem Thema ab – kuehlhaus/status/… ergibt
 * denselben Namen wie shelly/kuehlhaus/status/…, shellies/SHELLY1-b929cc
 * denselben wie shellies/shelly1-B929CC. Unter einem solchen Doppelgänger
 * könnte der gemeinsame Zugang Messwerte und Geräteangaben für das
 * geschützte Gerät einspeisen. „Shelly Gen2+ übersetzen", „Shelly Gen2+
 * Geräteinfo" und „Shelly Gen1 übersetzen" verwerfen deshalb alles, was für
 * ein Gerät dieser Liste unter einem anderen Präfix ankommt. Unter pm/#
 * darf der gemeinsame Zugang nicht schreiben – die Liste selbst kann er
 * nicht fälschen.
 *
 * Die Liste liegt im globalen Kontext (mqtt_geschuetzt): Gen1 und Gen2+
 * liegen auf verschiedenen Tabs, der Flow-Kontext reichte nicht.
 *
 * Ungültiges (kein JSON, kein Objekt, „geschuetzt" fehlt oder ist kein
 * Objekt, Gerätename oder Präfix leer oder mit + # NUL, Präfix länger als
 * 200 Zeichen) wird übergangen; es gilt die letzte gültige Liste. Ein
 * Eintrag „__proto__" taugt nicht als Schlüssel und wird ausgelassen – ein
 * solches Gerät nehmen die Shelly-Funktionen ohnehin nicht an.
 *
 * Nach einem Neustart von Node-RED ist die Liste leer, bis der Broker die
 * gespeicherte Nachricht beim Abonnieren schickt.
 *
 * Quittung (einziger Ausgang → „pm/status/nodered-schutz"): Jede
 * angenommene Liste bestätigt die Funktion retained mit QoS 1:
 *   { "ts": 1727200000000, "anzahl": 3, "zeit": 1727200000123 }
 * ts ist der Zeitstempel der angenommenen Liste (null, wenn sie keinen
 * numerischen hatte), anzahl die Zahl der geschützten Geräte, zeit der
 * Zeitpunkt der Annahme (ms). Läuft eine Installation mit alten, von Hand
 * geänderten Flows ohne diese Funktion, fehlt die Quittung oder bleibt bei
 * einem älteren ts stehen – daran ist zu erkennen, dass der Schutz nicht
 * wirkt. Ungültiges wird nicht quittiert; es bleibt die letzte Quittung
 * stehen, so wie die letzte gültige Liste gilt. Auch die Quittung liegt
 * unter pm/#, der gemeinsame Zugang kann sie nicht fälschen.
 */

const SCHLUESSEL = 'mqtt_geschuetzt';
const PRAEFIX_MAX = 200;
const QUITTUNG = 'pm/status/nodered-schutz';

function hat(objekt, schluessel) {
    return Object.prototype.hasOwnProperty.call(objekt, schluessel);
}

function brauchbar(text) {
    return typeof text === 'string' && text !== '' && !/[+#\u0000]/.test(text);
}

function istObjekt(wert) {
    return wert !== null && typeof wert === 'object' && !Array.isArray(wert);
}

function uebergehen(grund) {
    const bisher = global.get(SCHLUESSEL);
    const anzahl = bisher ? Object.keys(bisher).length : 0;
    node.warn('Liste der MQTT-Zugänge übergangen (' + grund + '), es gilt die letzte gültige.');
    node.status({ fill: 'yellow', shape: 'ring', text: 'ungültig übergangen – ' + anzahl + ' geschützt' });
    return null;
}

let daten = msg.payload;
if (Buffer.isBuffer(daten)) {
    daten = daten.toString('utf8');
}
if (typeof daten === 'string') {
    try {
        daten = JSON.parse(daten);
    } catch (e) {
        return uebergehen('kein JSON');
    }
}
if (!istObjekt(daten) || !hat(daten, 'geschuetzt') || !istObjekt(daten.geschuetzt)) {
    return uebergehen('„geschuetzt" fehlt');
}

const neu = {};
for (const geraet of Object.keys(daten.geschuetzt)) {
    if (geraet === '__proto__') {
        continue;
    }
    const praefix = daten.geschuetzt[geraet];
    if (!brauchbar(geraet) || !brauchbar(praefix) || praefix.length > PRAEFIX_MAX) {
        return uebergehen('ungültiger Eintrag');
    }
    neu[geraet] = praefix;
}

global.set(SCHLUESSEL, neu);
const anzahl = Object.keys(neu).length;
node.status({ fill: 'green', shape: 'dot', text: anzahl + ' geschützt' });
return {
    topic: QUITTUNG,
    retain: true,
    qos: 1,
    payload: JSON.stringify({
        ts: typeof daten.ts === 'number' && Number.isFinite(daten.ts) ? daten.ts : null,
        anzahl,
        zeit: Date.now(),
    }),
};

/*
 * Shelly Gen2+ übersetzen
 *
 * Shelly Plus/Pro/Gen3/Gen4 schicken mit „Generic status update over MQTT"
 * den vollständigen Status jeder Komponente auf
 *     <präfix>/status/<komponente>      z. B. shellypro3em-a0b1c2d3e4f5/status/em:0
 * und ihren Verbindungszustand auf
 *     <präfix>/online                   "true" / "false"
 * Das Präfix ist ab Werk die Geräte-ID; unterstützt wird zusätzlich
 * shelly/<name>/…, wie es viele im Gerät von Hand eintragen.
 *
 * Ausgang 1: normalisierte Messwerte (dasselbe Format, das der PHP-Sammler
 *            auf pm/messwert/<gerät>/<kanal> schickt) und Punkte für die
 *            Geräteliste – beides geht weiter an „Messwert → Line Protocol".
 * Ausgang 2: RPC-Anfrage Shelly.GetDeviceInfo an <präfix>/rpc mit dem
 *            Absender (src) <präfix>/pm-nodered. Der Shelly antwortet an
 *            <src>/rpc, also <präfix>/pm-nodered/rpc – im Baum des Geräts.
 *            Nur dorthin darf ein Shelly mit eigenem MQTT-Zugang schreiben
 *            (Benutzer = Präfix, Recht auf <präfix>/#), und genau diesen
 *            Baum sperrt der Broker für den gemeinsamen Zugang „shelly",
 *            sobald der eigene Zugang bestätigt ist. Bleibt die Antwort 60 s
 *            aus, fragt der Flow beim nächsten Status des Geräts genau
 *            einmal mit dem alten Absender pm-nodered (Antwort auf
 *            pm-nodered/rpc). Die Antworten wertet „Shelly Gen2+ Geräteinfo"
 *            aus.
 *
 * Für ein Gerät mit eigenem MQTT-Zugang (Liste aus „MQTT-Zugänge merken")
 * gilt nur sein eigenes Präfix: Meldungen unter einem anderen Präfix, das
 * denselben Gerätenamen ergibt, werden verworfen.
 *
 * Einheiten, wie sie der Shelly liefert und die Oberfläche erwartet:
 * u V, i A, p W, s VA, pf ohne Einheit, f Hz, e/e_rueck Wh (Zählerstand).
 */

const ABSENDER = 'pm-nodered';
const INFO_ALLE_MS = 6 * 3600 * 1000;    // Geräteinfo alle 6 h auffrischen
const RUECKFALL_NACH_MS = 60 * 1000;     // ohne Antwort: einmal mit altem Absender
const ANFRAGE_VERFALL_MS = 10 * 60 * 1000;

// Themen, die zwar auf +/status/# oder +/online passen, aber nicht von
// einem Shelly kommen: die eigenen (pm/status/nodered!), die Absender der
// Oberfläche und von Node-RED (pm-nodered, pm-steuerung-…, pm-konto-…),
// Gen1 und der Broker selbst.
function fremd(e) {
    return e === 'pm' || e.startsWith('pm-') || e === 'shellies' || e === '$SYS';
}

// Gerätename für Tags: letztes Segment des Präfixes, klein, nur
// [a-z0-9_.-] – alles andere wird zu „-". So bleibt der Name in Themen,
// Adressen und InfluxQL ohne Anführungszeichen benutzbar.
function geraeteName(praefix) {
    const teile = String(praefix).split('/');
    return teile[teile.length - 1].toLowerCase().replace(/[^a-z0-9_.-]/g, '-');
}

function zahl(wert) {
    return typeof wert === 'number' && Number.isFinite(wert) ? wert : undefined;
}

function einsNull(wert) {
    return typeof wert === 'boolean' ? (wert ? 1 : 0) : undefined;
}

// Entfernt leere Werte; liefert undefined, wenn nichts übrig bleibt – dann
// entsteht für diese Phase gar kein Punkt.
function bereinigt(werte) {
    const aus = {};
    for (const k of Object.keys(werte)) {
        if (werte[k] !== undefined && werte[k] !== null) {
            aus[k] = werte[k];
        }
    }
    return Object.keys(aus).length > 0 ? aus : undefined;
}

// Thema zerlegen: shelly/<name>/status/… oder <präfix>/status/…
const thema = String(msg.topic || '');
const teile = thema.split('/');
let praefix;
let art;
let komponente;
if (teile[0] === 'shelly' && teile.length >= 3
    && (teile[2] === 'status' || teile[2] === 'online' || teile[2].startsWith('pm-'))) {
    praefix = teile.slice(0, 2).join('/');
    art = teile[2];
    komponente = teile.slice(3).join('/');
} else {
    praefix = teile[0];
    art = teile[1] || '';
    komponente = teile.slice(2).join('/');
}
// Im Baum eines Geräts liegen auch die Absender von Oberfläche und Node-RED
// (<präfix>/pm-…/rpc) – das sind keine Meldungen des Geräts.
if (!praefix || fremd(teile[0]) || art.startsWith('pm-')) {
    return null;
}

const geraet = geraeteName(praefix);
// „__proto__" taugt nicht als Schlüssel im Flow-Kontext (die Zuweisung
// setzte den Prototyp, statt einen Eintrag anzulegen).
if (geraet === '__proto__') {
    return null;
}
// Geräte mit eigenem MQTT-Zugang (globaler Kontext, „MQTT-Zugänge merken"):
// Gerätename → genaues Präfix. Ihren Baum sperrt der Broker für den
// gemeinsamen Zugang, nicht aber einen Doppelgänger mit demselben
// Gerätenamen (kuehlhaus/… statt shelly/kuehlhaus/…). Was für ein solches
// Gerät unter einem anderen Präfix ankommt, stammt nicht von ihm.
const geschuetzt = global.get('mqtt_geschuetzt') || {};
if (Object.prototype.hasOwnProperty.call(geschuetzt, geraet) && geschuetzt[geraet] !== praefix) {
    return null;
}
const jetzt = Date.now();
let text = msg.payload;
if (Buffer.isBuffer(text)) {
    text = text.toString('utf8');
}
text = typeof text === 'string' ? text : JSON.stringify(text);

function messwert(kanal, phasen, zustand) {
    const nutzlast = { ts: jetzt, typ: 'shelly' };
    let leer = true;
    const p = {};
    for (const phase of Object.keys(phasen || {})) {
        const werte = phasen[phase] ? bereinigt(phasen[phase]) : undefined;
        if (werte) {
            p[phase] = werte;
            leer = false;
        }
    }
    if (!leer) {
        nutzlast.phasen = p;
    }
    const z = zustand ? bereinigt(zustand) : undefined;
    if (z) {
        nutzlast.zustand = z;
        leer = false;
    }
    return leer ? null : { topic: 'pm/messwert/' + geraet + '/' + kanal, payload: nutzlast };
}

// ------------------------------------------------------------ online
if (art === 'online' && komponente === '') {
    const t = text.trim().toLowerCase();
    if (t !== 'true' && t !== 'false') {
        return null;
    }
    return [messwert('geraet', null, { online: t === 'true' ? 1 : 0 }), null];
}

if (art !== 'status' || !/^[a-z0-9_]+(:\d+)?$/.test(komponente)) {
    return null;
}

let s;
try {
    s = JSON.parse(text);
} catch (e) {
    return null;
}
if (s === null || typeof s !== 'object' || Array.isArray(s)) {
    return null;
}

const [typ, nummer] = komponente.split(':');
const nr = nummer === undefined ? '0' : nummer;
const ausgabe = [];

// ------------------------------------------------------------ Komponenten
if (typ === 'switch') {
    ausgabe.push(messwert(komponente, {
        sum: {
            u: zahl(s.voltage),
            i: zahl(s.current),
            p: zahl(s.apower),
            pf: zahl(s.pf),
            f: zahl(s.freq),
            e: s.aenergy ? zahl(s.aenergy.total) : undefined,
            e_rueck: s.ret_aenergy ? zahl(s.ret_aenergy.total) : undefined,
        },
    }, {
        schalter: einsNull(s.output),
        temperatur: s.temperature ? zahl(s.temperature.tC) : undefined,
    }));
} else if (typ === 'em') {
    // Pro 3EM im Drehstrom-Profil: a/b/c sind die Phasen L1/L2/L3.
    const phase = (x) => ({
        u: zahl(s[x + '_voltage']),
        i: zahl(s[x + '_current']),
        p: zahl(s[x + '_act_power']),
        s: zahl(s[x + '_aprt_power']),
        pf: zahl(s[x + '_pf']),
        f: zahl(s[x + '_freq']),
    });
    ausgabe.push(messwert('em:' + nr, {
        L1: phase('a'),
        L2: phase('b'),
        L3: phase('c'),
        N: { i: zahl(s.n_current) },
        sum: { i: zahl(s.total_current), p: zahl(s.total_act_power), s: zahl(s.total_aprt_power) },
    }));
} else if (typ === 'emdata') {
    // Zählerstände – bewusst derselbe Kanal wie die Leistung (em:N), damit
    // Leistung und Energie einer Messstelle zusammen abgefragt werden können.
    const phase = (x) => ({
        e: zahl(s[x + '_total_act_energy']),
        e_rueck: zahl(s[x + '_total_act_ret_energy']),
    });
    ausgabe.push(messwert('em:' + nr, {
        L1: phase('a'),
        L2: phase('b'),
        L3: phase('c'),
        sum: { e: zahl(s.total_act), e_rueck: zahl(s.total_act_ret) },
    }));
} else if (typ === 'em1') {
    ausgabe.push(messwert('em1:' + nr, {
        sum: {
            u: zahl(s.voltage),
            i: zahl(s.current),
            p: zahl(s.act_power),
            s: zahl(s.aprt_power),
            pf: zahl(s.pf),
            f: zahl(s.freq),
        },
    }));
} else if (typ === 'em1data') {
    ausgabe.push(messwert('em1:' + nr, {
        sum: { e: zahl(s.total_act_energy), e_rueck: zahl(s.total_act_ret_energy) },
    }));
} else if (typ === 'pm1') {
    ausgabe.push(messwert(komponente, {
        sum: {
            u: zahl(s.voltage),
            i: zahl(s.current),
            p: zahl(s.apower),
            pf: zahl(s.pf),
            f: zahl(s.freq),
            e: s.aenergy ? zahl(s.aenergy.total) : undefined,
            e_rueck: s.ret_aenergy ? zahl(s.ret_aenergy.total) : undefined,
        },
    }));
} else if (typ === 'temperature') {
    ausgabe.push(messwert(komponente, null, { temperatur: zahl(s.tC) }));
} else if (typ === 'input') {
    // Digitaleingang: state true/false. Analogeingang: percent.
    ausgabe.push(messwert(komponente, null, {
        eingang: einsNull(s.state) !== undefined ? einsNull(s.state) : zahl(s.percent),
    }));
}

// ------------------------------------------------------------ Geräteliste
// Beim ersten Sehen eines Geräts (und danach alle 6 h) nach Modell und
// Firmware fragen. Zusätzlich sofort einen Punkt mit Präfix und Generation
// schreiben: dann steht das Gerät in der Liste, auch wenn es auf RPC über
// MQTT nicht antwortet – und die Oberfläche kennt das Präfix, unter dem sie
// ihm Befehle schicken kann.
const bekannte = flow.get('gen2_geraete') || {};
// nur eigene Schlüssel – ein Gerät „constructor" fände sonst Object.prototype
const eintrag = Object.prototype.hasOwnProperty.call(bekannte, geraet) ? bekannte[geraet] : undefined;
const offen = flow.get('gen2_rpc') || {};
let anfrage = null;

// Anfrage stellen und als offen merken. Die Antwort nennt als src nur die
// Geräte-ID; mit eigenem Präfix (shelly/<name>) wäre daraus der Gerätename
// nicht abzuleiten. Deshalb steht hier, welche Anfrage an welches Gerät ging
// und mit welchem Absender – nur eine Antwort auf <src>/rpc mit dst = src
// gilt („Shelly Gen2+ Geräteinfo").
//
// Die id ist zufällig, nicht fortlaufend: Beim Rückfall auf pm-nodered/rpc
// kann jeder mit dem gemeinsamen Zugang dorthin schreiben, die Anfrage an
// ein gesperrtes Gerät aber nicht mitlesen – eine fortlaufende Nummer wäre
// zu erraten.
function rpcAnfrage(src, versuch) {
    let id;
    do {
        id = 1000000 + Math.floor(Math.random() * 1999000000);
    } while (Object.prototype.hasOwnProperty.call(offen, String(id)));
    offen[id] = { geraet, praefix, src, t: jetzt, versuch };
    flow.set('gen2_rpc', offen);
    return {
        topic: praefix + '/rpc',
        payload: JSON.stringify({ id, src, method: 'Shelly.GetDeviceInfo' }),
    };
}

// Wartet diese Anfrage noch auf ihren Rückfall (Versuch 1, zu dem es keinen
// Versuch 2 gibt)?
function wartetAufRueckfall(a) {
    return a.versuch === 1 && !Object.keys(offen).some((id) => offen[id].versuch === 2
        && offen[id].geraet === a.geraet && offen[id].praefix === a.praefix);
}

if (!eintrag || jetzt - eintrag.angefragt > INFO_ALLE_MS || eintrag.praefix !== praefix) {
    bekannte[geraet] = { praefix, angefragt: jetzt };
    flow.set('gen2_geraete', bekannte);

    // Aufräumen. Die neue Runde ersetzt die alten Anfragen dieses Geräts.
    // Sonst verfällt eine offene Anfrage nach 10 min – ein Versuch 1, dem
    // der Rückfall noch fehlt, aber erst nach 6 h: Der Rückfall kommt mit
    // der nächsten Statusmeldung des Geräts, und die lässt bei einem Gerät
    // ohne Last auch einmal länger auf sich warten.
    const verfallen = Object.keys(offen).filter((id) => {
        const a = offen[id];
        const frist = wartetAufRueckfall(a) ? INFO_ALLE_MS : ANFRAGE_VERFALL_MS;
        return a.geraet === geraet || !(jetzt - a.t <= frist);
    });
    for (const id of verfallen) {
        delete offen[id];
    }
    // Versuch 1: Absender im Baum des Geräts
    anfrage = rpcAnfrage(praefix + '/' + ABSENDER, 1);
    ausgabe.push({
        punkte: [{
            messung: 'geraet',
            tags: { geraet, typ: 'shelly' },
            felder: { generation: 2, praefix },
            ts: jetzt,
        }],
    });

    node.status({ fill: 'green', shape: 'dot', text: Object.keys(bekannte).length + ' Geräte' });
} else {
    // Versuch 2: Versuch 1 ist älter als 60 s und unbeantwortet (eine
    // Antwort löscht alle offenen Anfragen des Geräts) – dann einmal mit dem
    // alten Absender pm-nodered, für Geräte, die nicht in ihren eigenen Baum
    // antworten. Ein Shelly mit eigenem Zugang darf pm-nodered/rpc nicht
    // schreiben; seine Antwort auf Versuch 1 gilt weiterhin.
    const erster = Object.keys(offen).map((id) => offen[id])
        .find((a) => a.geraet === geraet && a.praefix === praefix && wartetAufRueckfall(a));
    if (erster && jetzt - erster.t > RUECKFALL_NACH_MS) {
        anfrage = rpcAnfrage(ABSENDER, 2);
    }
}

const messwerte = ausgabe.filter((m) => m !== null);
return [messwerte.length > 0 ? messwerte : null, anfrage];

/*
 * Shelly Gen2+ Geräteinfo
 *
 * Antwort auf Shelly.GetDeviceInfo (gestellt von „Shelly Gen2+ übersetzen").
 * Der Shelly antwortet an <src>/rpc. Versuch 1 hat den Absender
 * <präfix>/pm-nodered, die Antwort kommt also im Baum des Geräts an:
 *   Thema shelly/halle-3/pm-nodered/rpc
 *   { "id": 1234567, "src": "shellypro3em-a0b1c2d3e4f5", "dst": "shelly/halle-3/pm-nodered",
 *     "result": { "id": "shellypro3em-a0b1c2d3e4f5", "mac": "A0B1C2D3E4F5",
 *                 "model": "SPEM-003CEBEU", "gen": 2, "ver": "1.4.4",
 *                 "app": "Pro3EM", "name": "Hauptverteilung", … } }
 * Versuch 2 (nach 60 s ohne Antwort) hat den alten Absender pm-nodered,
 * die Antwort kommt auf pm-nodered/rpc mit "dst": "pm-nodered".
 *
 * Es gilt nur eine Antwort, die zu einer offenen Anfrage passt: gleiche id,
 * Thema = <src der Anfrage>/rpc, dst = src der Anfrage und keine „method"
 * (dann wäre es eine Anfrage oder Meldung, keine Antwort). Passt etwas
 * nicht, bleibt die Anfrage offen – eine falsche Nachricht verdrängt die
 * echte Antwort nicht.
 *
 * Fehlt die offene Anfrage (Node-RED wurde neu gestartet, während die
 * Antwort unterwegs war), zählt nur eine Antwort im Baum eines Geräts:
 * Gerät und Präfix ergeben sich dann aus dem Thema, so wie bei den
 * Statusmeldungen. Auf pm-nodered/rpc ist ohne Anfrage nicht zu erkennen,
 * von welchem Gerät die Antwort stammt – sie wird verworfen.
 *
 * Für ein Gerät mit eigenem MQTT-Zugang (Liste aus „MQTT-Zugänge merken")
 * zählt nur eine Antwort auf <sein präfix>/pm-nodered/rpc – weder eine
 * unter einem anderen Präfix mit demselben Gerätenamen noch eine auf
 * pm-nodered/rpc, wohin das Gerät gar nicht schreiben darf.
 *
 * Daraus entsteht ein Punkt der Messung „geraet" – aus ihr baut die
 * Oberfläche die Liste der Geräte:
 *   geraet,geraet=<g>,typ=shelly modell="…",name="…",firmware="…",generation=2,mac="…",praefix="…"
 */

const ABSENDER = 'pm-nodered';

// Wie in „Shelly Gen2+ übersetzen": kein Präfix eines Shelly.
function fremd(e) {
    return e === 'pm' || e.startsWith('pm-') || e === 'shellies' || e === '$SYS';
}

function geraeteName(text) {
    const teile = String(text).split('/');
    return teile[teile.length - 1].toLowerCase().replace(/[^a-z0-9_.-]/g, '-');
}

function hat(objekt, schluessel) {
    return Object.prototype.hasOwnProperty.call(objekt, schluessel);
}

// Thema: pm-nodered/rpc (alter Absender) oder <präfix>/pm-nodered/rpc
const thema = String(msg.topic || '');
let themaPraefix = '';
if (thema !== ABSENDER + '/rpc') {
    const treffer = /^(.+)\/pm-nodered\/rpc$/.exec(thema);
    if (!treffer) {
        return null;
    }
    themaPraefix = treffer[1];
}

let antwort = msg.payload;
if (Buffer.isBuffer(antwort)) {
    antwort = antwort.toString('utf8');
}
if (typeof antwort === 'string') {
    try {
        antwort = JSON.parse(antwort);
    } catch (e) {
        return null;
    }
}
if (antwort === null || typeof antwort !== 'object' || Array.isArray(antwort)) {
    return null;
}
if (hat(antwort, 'method') || !Number.isInteger(antwort.id) || (!hat(antwort, 'result') && !hat(antwort, 'error'))) {
    return null;
}

// Zu welcher Anfrage gehört die Antwort? Die Zuordnung steht im Flow-Kontext.
const offen = flow.get('gen2_rpc') || {};
const schluessel = String(antwort.id);
const anfrage = hat(offen, schluessel) ? offen[schluessel] : null;
let geraet;
let praefix;
if (anfrage) {
    if (thema !== anfrage.src + '/rpc' || antwort.dst !== anfrage.src) {
        // gehört nicht zu dieser Anfrage – sie bleibt offen
        return null;
    }
    geraet = anfrage.geraet;
    praefix = anfrage.praefix;
} else {
    // Ohne Anfrage nur im Baum eines Geräts: <id> oder shelly/<name>, wie in
    // „Shelly Gen2+ übersetzen", und dst muss der Absender in diesem Baum sein.
    const teile = themaPraefix.split('/');
    const passt = themaPraefix !== ''
        && antwort.dst === themaPraefix + '/' + ABSENDER
        && teile.every((t) => t !== '')
        && !fremd(teile[0])
        && (teile.length === 1 || (teile.length === 2 && teile[0] === 'shelly'));
    if (!passt) {
        return null;
    }
    geraet = geraeteName(themaPraefix);
    praefix = themaPraefix;
}

// Gerät mit eigenem MQTT-Zugang (globaler Kontext, „MQTT-Zugänge merken"):
// Es schreibt nur in seinen Baum, die Antwort kommt also auf
// <sein präfix>/pm-nodered/rpc. Eine Antwort unter einem Doppelgänger mit
// demselben Gerätenamen oder auf pm-nodered/rpc stammt nicht von ihm – die
// Anfrage bleibt offen.
const geschuetzt = global.get('mqtt_geschuetzt') || {};
if (hat(geschuetzt, geraet) && geschuetzt[geraet] !== themaPraefix) {
    return null;
}

if (anfrage) {
    // Beantwortet: diese Anfrage und die übrigen Versuche für dasselbe Gerät
    // sind erledigt (sonst stellte „übersetzen" noch einen Versuch 2).
    for (const id of Object.keys(offen)) {
        if (id === schluessel || (offen[id].geraet === anfrage.geraet && offen[id].praefix === anfrage.praefix)) {
            delete offen[id];
        }
    }
    flow.set('gen2_rpc', offen);
}

if (antwort.error || antwort.result === null || typeof antwort.result !== 'object' || Array.isArray(antwort.result)) {
    const grund = antwort.error ? (antwort.error.message || JSON.stringify(antwort.error)) : 'keine Nutzdaten';
    node.warn('Geräteinfo von ' + geraet + ' nicht erhalten: ' + String(grund).slice(0, 200));
    return null;
}

const r = antwort.result;
const text = (wert) => (typeof wert === 'string' && wert !== '' ? wert : undefined);

node.status({ fill: 'green', shape: 'dot', text: geraet + ': ' + (text(r.app) || text(r.model) || '?') });

return {
    punkte: [{
        messung: 'geraet',
        tags: { geraet, typ: 'shelly' },
        felder: {
            modell: text(r.model),
            // „app" ist der lesbare Produktname (Pro3EM, PlusPlugS …) –
            // das Modell ist nur die Bestellnummer.
            produkt: text(r.app),
            name: text(r.name),
            firmware: text(r.ver) || text(r.fw_id),
            // Gen3/Gen4 melden sich mit gen 3/4 – das geht so weiter.
            generation: typeof r.gen === 'number' ? r.gen : 2,
            mac: text(r.mac),
            praefix,
        },
        ts: Date.now(),
    }],
};

/*
 * Shelly Gen1 übersetzen
 *
 * Gen1-Geräte (Shelly 1PM, 2.5, Plug S, EM, 3EM …) veröffentlichen jeden
 * Wert auf einem eigenen Thema unter shellies/<id>/…:
 *   relay/N                 "on" / "off" / "overpower"
 *   relay/N/power           W
 *   relay/N/energy          Wattminuten (!) seit dem letzten Neustart
 *   emeter/N/power|voltage|current|pf|reactive_power|total|total_returned
 *                           total/total_returned in Wh
 *   input/N                 "0" / "1"
 *   online                  "true" / "false"
 *   temperature             °C
 *   announce                JSON mit id, model, mac, ip, fw_ver
 * und shellies/announce als Antwort auf „announce" an shellies/command.
 * Ein Gerät mit eigenem MQTT-Zugang (Benutzer = <id>) darf nur in seinen
 * Baum shellies/<id>/# schreiben – shellies/announce verwirft der Broker
 * still. Die Geräteinfo kommt dann aus shellies/<id>/announce, das das
 * Gerät beim Verbinden mit dem Broker ebenfalls schickt.
 *
 * Themen unter shellies/<id>/pm-…/ (Prüfungen der Oberfläche im Baum des
 * Geräts, z. B. shellies/<id>/pm-probe/…) stammen nicht vom Gerät und
 * werden übergangen.
 *
 * Für ein Gerät mit eigenem MQTT-Zugang (Liste aus „MQTT-Zugänge merken")
 * gilt nur sein genaues Präfix shellies/<id>: Meldungen unter einer anders
 * geschriebenen ID mit demselben Gerätenamen und Einträge auf
 * shellies/announce werden verworfen.
 *
 * Ausgang: normalisierte Messwerte und Punkte für die Geräteliste – weiter
 * an „Messwert → Line Protocol".
 *
 * Die Summe über die Phasen eines EM/3EM (phase=sum) rechnet Gen1 nicht
 * selbst. Sie entsteht hier, sobald von allen bisher gesehenen Phasen ein
 * neuer Wert vorliegt, der jünger als 30 s ist. Ältere Werte zu addieren
 * ergäbe eine Summe, die es so nie gab.
 */

const INFO_ALLE_MS = 6 * 3600 * 1000;
const FRISCH_MS = 30 * 1000;
const EMETER_FELDER = {
    power: 'p',
    voltage: 'u',
    current: 'i',
    pf: 'pf',
    reactive_power: 'q',
    total: 'e',
    total_returned: 'e_rueck',
};
const SUMMEN_FELDER = ['p', 'e', 'e_rueck'];

function geraeteName(id) {
    return String(id).toLowerCase().replace(/[^a-z0-9_.-]/g, '-');
}

// Eine Geräte-ID ist genau eine Themenebene. „__proto__" taugt nicht als
// Schlüssel im Flow-Kontext – die Zuweisung setzte den Prototyp, statt
// einen Eintrag anzulegen.
function brauchbareId(id) {
    return typeof id === 'string' && /^[^/+#]+$/.test(id) && geraeteName(id) !== '__proto__';
}

// Eintrag im Flow-Kontext, nur eigene Schlüssel – ein Gerät „constructor"
// fände sonst die Eigenschaft von Object.prototype.
function eigen(objekt, schluessel) {
    return Object.prototype.hasOwnProperty.call(objekt, schluessel) ? objekt[schluessel] : undefined;
}

// Geräte mit eigenem MQTT-Zugang (globaler Kontext, „MQTT-Zugänge merken"):
// Gerätename → genaues Präfix. Ihren Baum sperrt der Broker für den
// gemeinsamen Zugang, nicht aber einen Doppelgänger mit demselben
// Gerätenamen (shellies/SHELLY1-b929cc statt shellies/shelly1-B929CC,
// shellies/kuehlhaus für shelly/kuehlhaus). Kommt eine Meldung für ein
// solches Gerät nicht aus seinem Baum, stammt sie nicht von ihm.
const geschuetzt = global.get('mqtt_geschuetzt') || {};
function fremderBaum(id, praefix) {
    const p = eigen(geschuetzt, geraeteName(id));
    return p !== undefined && p !== praefix;
}

function alsZahl(text) {
    const t = String(text).trim();
    if (t === '') {
        return undefined;
    }
    const n = Number(t);
    return Number.isFinite(n) ? n : undefined;
}

const teile = String(msg.topic || '').split('/');
if (teile[0] !== 'shellies' || teile.length < 2 || !brauchbareId(teile[1])) {
    return null;
}
// Prüf-Themen der Oberfläche im Baum eines Geräts: kein Messwert und auch
// kein Lebenszeichen des Geräts.
if (teile.length >= 3 && teile[2].startsWith('pm-')) {
    return null;
}
let text = msg.payload;
if (Buffer.isBuffer(text)) {
    text = text.toString('utf8');
}
text = typeof text === 'string' ? text : JSON.stringify(text);
const jetzt = Date.now();

function geraetePunkt(id, felder) {
    return {
        punkte: [{
            messung: 'geraet',
            tags: { geraet: geraeteName(id), typ: 'shelly' },
            felder: Object.assign({ generation: 1, praefix: 'shellies/' + id }, felder),
            ts: jetzt,
        }],
    };
}

// ------------------------------------------------------------ announce
if (teile[1] === 'announce' || (teile.length === 3 && teile[2] === 'announce')) {
    let a;
    try {
        a = JSON.parse(text);
    } catch (e) {
        return null;
    }
    // Auf shellies/announce nennt die Nutzlast das Gerät – auch dann genau
    // eine Themenebene, sonst entstünde ein Präfix, unter dem kein Gerät zu
    // erreichen ist.
    const id = teile[1] === 'announce' ? a && a.id : teile[1];
    if (!a || typeof a !== 'object' || !brauchbareId(id)) {
        return null;
    }
    // shellies/announce liegt in keinem Gerätebaum – ein Gerät mit eigenem
    // Zugang darf dort nicht schreiben.
    if (fremderBaum(id, teile[1] === 'announce' ? '' : 'shellies/' + id)) {
        return null;
    }
    const txt = (wert) => (typeof wert === 'string' && wert !== '' ? wert : undefined);
    return geraetePunkt(id, {
        modell: txt(a.model),
        firmware: txt(a.fw_ver),
        mac: txt(a.mac),
        ip: txt(a.ip),
    });
}

// shellies/command und Befehlsthemen (…/command) schickt Node-RED bzw. die
// Oberfläche selbst – das sind keine Messwerte.
if (teile[1] === 'command' || teile[teile.length - 1] === 'command') {
    return null;
}

const id = teile[1];
if (fremderBaum(id, 'shellies/' + id)) {
    return null;
}
const geraet = geraeteName(id);
const rest = teile.slice(2);
const ausgabe = [];

function messwert(kanal, phasen, zustand) {
    const nutzlast = { ts: jetzt, typ: 'shelly' };
    if (phasen) {
        nutzlast.phasen = phasen;
    }
    if (zustand) {
        nutzlast.zustand = zustand;
    }
    return { topic: 'pm/messwert/' + geraet + '/' + kanal, payload: nutzlast };
}

// Das Gerät in die Liste eintragen, sobald es sich überhaupt meldet –
// announce kommt nur beim Verbinden und auf Nachfrage.
const bekannte = flow.get('gen1_geraete') || {};
const zuletzt = eigen(bekannte, geraet);
if (!zuletzt || jetzt - zuletzt > INFO_ALLE_MS) {
    bekannte[geraet] = jetzt;
    flow.set('gen1_geraete', bekannte);
    ausgabe.push(geraetePunkt(id, {}));
    node.status({ fill: 'green', shape: 'dot', text: Object.keys(bekannte).length + ' Geräte' });
}

if (rest.length === 1 && rest[0] === 'online') {
    const t = text.trim().toLowerCase();
    if (t === 'true' || t === 'false') {
        ausgabe.push(messwert('geraet', null, { online: t === 'true' ? 1 : 0 }));
    }
} else if (rest.length === 1 && rest[0] === 'temperature') {
    const wert = alsZahl(text);
    if (wert !== undefined) {
        ausgabe.push(messwert('geraet', null, { temperatur: wert }));
    }
} else if (rest[0] === 'relay' && /^\d+$/.test(rest[1] || '')) {
    const kanal = 'relay:' + rest[1];
    if (rest.length === 2) {
        const t = text.trim().toLowerCase();
        if (t === 'on' || t === 'off' || t === 'overpower') {
            // overpower: das Gerät hat wegen Überlast abgeschaltet
            ausgabe.push(messwert(kanal, null, { schalter: t === 'on' ? 1 : 0 }));
        }
    } else if (rest.length === 3 && rest[2] === 'power') {
        const wert = alsZahl(text);
        if (wert !== undefined) {
            ausgabe.push(messwert(kanal, { sum: { p: wert } }));
        }
    } else if (rest.length === 3 && rest[2] === 'energy') {
        // Gen1 zählt hier in Wattminuten – durch 60 sind es Wh wie überall.
        const wert = alsZahl(text);
        if (wert !== undefined) {
            ausgabe.push(messwert(kanal, { sum: { e: wert / 60 } }));
        }
    }
} else if (rest[0] === 'input' && rest.length === 2 && /^\d+$/.test(rest[1])) {
    const wert = alsZahl(text);
    if (wert !== undefined) {
        ausgabe.push(messwert('input:' + rest[1], null, { eingang: wert }));
    }
} else if (rest[0] === 'emeter' && rest.length === 3 && /^\d+$/.test(rest[1]) && EMETER_FELDER[rest[2]]) {
    const feld = EMETER_FELDER[rest[2]];
    const wert = alsZahl(text);
    const nr = Number(rest[1]);
    if (wert !== undefined && nr <= 2) {
        const phase = 'L' + (nr + 1);
        ausgabe.push(messwert('emeter', { [phase]: { [feld]: wert } }));

        if (SUMMEN_FELDER.includes(feld)) {
            // Je Gerät: letzter Wert je Phase und Feld mit laufender Nummer.
            // Summiert wird, wenn jede bekannte Phase seit der letzten Summe
            // dieses Feldes einen neuen und noch frischen Wert hat.
            //
            // Wie viele Phasen ein Gerät hat (EM: 2, 3EM: 3), sagt es nicht.
            // Es veröffentlicht aber in jeder Runde alle – erst wenn eine
            // Phase zum zweiten Mal kommt, ist eine Runde vorbei und die
            // Liste vollständig. Vorher entstünde nach dem Start eine
            // „Summe" aus nur einer Phase.
            //
            // Die Runde läuft emeter/0, /1, /2 der Reihe nach. Summiert wird
            // deshalb beim Wert der höchsten Phase: dann stammen alle
            // Summanden aus derselben Runde.
            const alle = flow.get('gen1_emeter') || {};
            const g = eigen(alle, geraet) || { nr: 0, phasen: {}, summe: {}, runde: {} };
            alle[geraet] = g;
            g.nr++;
            g.phasen[phase] = g.phasen[phase] || {};
            if (g.phasen[phase][feld]) {
                g.runde[feld] = true;
            }
            g.phasen[phase][feld] = { w: wert, t: jetzt, nr: g.nr };

            const letzte = g.summe[feld] || 0;
            const bekanntePhasen = Object.keys(g.phasen).sort();
            const werte = bekanntePhasen.map((ph) => g.phasen[ph][feld]);
            const vollstaendig = g.runde[feld]
                && phase === bekanntePhasen[bekanntePhasen.length - 1]
                && werte.every((x) => x && x.nr > letzte && jetzt - x.t <= FRISCH_MS);
            if (vollstaendig) {
                g.summe[feld] = g.nr;
                const summe = werte.reduce((a, x) => a + x.w, 0);
                ausgabe.push(messwert('emeter', { sum: { [feld]: summe } }));
            }
            flow.set('gen1_emeter', alle);
        }
    }
}

return ausgabe.length > 0 ? [ausgabe] : null;

/*
 * Messwert → Line Protocol
 *
 * Die einzige Stelle, an der Line Protocol entsteht. Alle Wege – der
 * PHP-Sammler über MQTT, die Shelly-Übersetzer, die Geräteliste – laufen
 * hier durch. So gibt es genau eine Stelle, die Escaping und Feldtypen
 * richtig machen muss.
 *
 * Eingang, eines von beiden:
 *   a) normalisierter Messwert
 *        msg.topic   = "pm/messwert/<geraet>/<kanal>"
 *        msg.payload = JSON-Text oder Objekt:
 *          { ts, typ, modell, phasen: { L1: {u,i,p,…}, …, sum: {…} },
 *            zustand: { soc: 87, schalter: 1, motorzustand: "Läuft" } }
 *   b) fertige Punkte (Messungen außerhalb des Messwert-Schemas, etwa
 *      die Geräteliste)
 *        msg.punkte = [{ messung, tags: {…}, felder: {…}, ts }]
 *
 * Ausgang: msg.zeilen = ["strom,geraet=…,kanal=…,phase=L1,typ=shelly u=230.1,… 1727200000000", …]
 *
 * Warum so streng mit den Typen: InfluxDB legt den Typ eines Feldes mit dem
 * ersten geschriebenen Wert fest. Kommt einmal „p=5i" (Ganzzahl) und später
 * „p=5.2" (Float), weist die Datenbank jeden Wert des anderen Typs ab – für
 * den ganzen Shard, also bis zu einer Woche lang. Deshalb gilt:
 *   – jede Zahl geht als Float hinaus. Ohne „i" am Ende ist eine Zahl in
 *     Line Protocol bereits ein Float, „1" ist also richtig.
 *   – Wahrheitswerte werden 1/0, ebenfalls als Float.
 *   – nur echte Texte werden String-Felder.
 *   – null, NaN und ±Infinity fallen weg; ein Punkt ohne Felder wird gar
 *     nicht geschrieben (InfluxDB würde die ganze Zeile ablehnen).
 */

const ZAHL_ALS_TEXT = /^\s*[-+]?(\d+\.?\d*|\.\d+)([eE][-+]?\d+)?\s*$/;

// Messungsname: Komma und Leerzeichen trennen in Line Protocol die Teile
// einer Zeile und müssen deshalb maskiert werden.
function maskiereMessung(text) {
    return String(text)
        .replace(/[\r\n]+/g, ' ')
        .replace(/\\/g, '\\\\')
        .replace(/([, ])/g, '\\$1');
}

// Tag-Schlüssel, Tag-Werte und Feldschlüssel: zusätzlich das
// Gleichheitszeichen. Der Backslash selbst wird ebenfalls verdoppelt –
// sonst würde ein Wert, der auf „\" endet, das folgende Komma maskieren
// und die Zeile zerlegen. Zeilenumbrüche beenden in Line Protocol eine
// Zeile und werden zu Leerzeichen.
function maskiereSchluessel(text) {
    return String(text)
        .replace(/[\r\n]+/g, ' ')
        .replace(/\\/g, '\\\\')
        .replace(/([,= ])/g, '\\$1');
}

// „time" ist in InfluxDB kein zulässiger Schlüssel, und Schlüssel mit „_"
// vorn sind in 2.x für interne Spalten reserviert (_measurement, _field …).
function zulaessigerSchluessel(schluessel) {
    return schluessel !== '' && schluessel !== 'time' && schluessel[0] !== '_';
}

// Liefert den Feldwert als Text für Line Protocol oder null, wenn der Wert
// nicht geschrieben werden soll.
//   zahlenAusText: Zahlen, die als Text ankommen ("230.1"), werden zu Floats.
//   Das gilt nur für Messwerte (phasen) – dort ist jeder Wert eine Zahl. Im
//   Zustand sind Texte erlaubt; dort bleibt ein Text ein Text, sonst hätte
//   ein Feld je nach Inhalt mal den einen, mal den anderen Typ.
function feldwert(wert, zahlenAusText) {
    if (typeof wert === 'boolean') {
        return wert ? '1' : '0';
    }
    if (typeof wert === 'string' && zahlenAusText && ZAHL_ALS_TEXT.test(wert)) {
        wert = Number(wert);
    }
    if (typeof wert === 'number') {
        // String(1) ergibt "1" – in Line Protocol ein Float, kein Integer.
        return Number.isFinite(wert) ? String(wert) : null;
    }
    if (typeof wert === 'string') {
        return '"' + wert
            .replace(/[\r\n]+/g, ' ')
            .replace(/\\/g, '\\\\')
            .replace(/"/g, '\\"') + '"';
    }
    // null, undefined, Objekte, Listen: nicht darstellbar
    return null;
}

// Zeitstempel in Millisekunden (die Schreibanfrage läuft mit precision=ms).
// Sekunden, Mikro- und Nanosekunden werden erkannt und umgerechnet – ein
// Sammler, der sich in der Einheit vertut, landet sonst im Jahr 1970 oder
// weit in der Zukunft, und niemand findet die Werte wieder.
function zeitstempel(ts) {
    let t = ts;
    if (typeof t === 'string' && t.trim() !== '') {
        t = Number(t);
    }
    if (typeof t !== 'number' || !Number.isFinite(t) || t <= 0) {
        return Date.now();
    }
    while (t > 1e14) {
        t = t / 1000;          // µs → ms, ns → µs → ms
    }
    if (t < 1e11) {
        t = t * 1000;          // Sekunden → ms
    }
    return Math.round(t);
}

// Baut eine Zeile oder liefert null, wenn kein einziges Feld übrig bleibt.
function zeile(messung, tags, felder, ts, zahlenAusText) {
    const teile = [];
    for (const schluessel of Object.keys(felder || {})) {
        if (!zulaessigerSchluessel(schluessel)) {
            continue;
        }
        const wert = feldwert(felder[schluessel], zahlenAusText);
        if (wert !== null) {
            teile.push(maskiereSchluessel(schluessel) + '=' + wert);
        }
    }
    if (teile.length === 0) {
        return null;
    }
    // Tags ohne Wert sind in Line Protocol unzulässig und fallen weg. Die
    // Sortierung nach Schlüssel empfiehlt InfluxDB – sie spart dort Arbeit.
    const tagText = Object.keys(tags || {})
        .filter((k) => zulaessigerSchluessel(k) && tags[k] !== undefined && tags[k] !== null && String(tags[k]) !== '')
        .sort()
        .map((k) => ',' + maskiereSchluessel(k) + '=' + maskiereSchluessel(tags[k]))
        .join('');
    return maskiereMessung(messung) + tagText + ' ' + teile.join(',') + ' ' + zeitstempel(ts);
}

function istObjekt(wert) {
    return wert !== null && typeof wert === 'object' && !Array.isArray(wert);
}

// Zähler für die Statusanzeige – nur alle zwei Sekunden auffrischen, damit
// ein offener Editor nicht mit Statusmeldungen überschwemmt wird.
const zaehler = context.get('zaehler') || { zeilen: 0, ungueltig: 0, angezeigt: 0 };
context.set('zaehler', zaehler);

function status() {
    const jetzt = Date.now();
    if (jetzt - zaehler.angezeigt < 2000) {
        return;
    }
    zaehler.angezeigt = jetzt;
    node.status({
        fill: zaehler.ungueltig > 0 ? 'yellow' : 'green',
        shape: 'dot',
        text: zaehler.zeilen + ' Zeilen' + (zaehler.ungueltig > 0 ? ', ' + zaehler.ungueltig + ' ungültig' : ''),
    });
}

function ungueltig(grund) {
    zaehler.ungueltig++;
    // Nicht jede kaputte Nachricht ins Protokoll – eine Meldung je Minute
    // genügt, um den Fehler zu finden.
    const jetzt = Date.now();
    if (!zaehler.gewarnt || jetzt - zaehler.gewarnt > 60000) {
        zaehler.gewarnt = jetzt;
        node.warn('Messwert verworfen (' + grund + '): ' + String(msg.topic || '(ohne Thema)'));
    }
    status();
    return null;
}

const punkte = [];

if (Array.isArray(msg.punkte)) {
    for (const p of msg.punkte) {
        if (istObjekt(p) && p.messung) {
            punkte.push({ messung: p.messung, tags: p.tags || {}, felder: p.felder || {}, ts: p.ts, zahlen: false });
        }
    }
} else {
    // pm/messwert/<geraet>/<kanal> – das erste Segment (Präfix) wird nicht
    // geprüft, damit ein anderes Präfix nur im mqtt-in-Node geändert werden
    // muss. Ein Kanal darf weitere „/" enthalten.
    const teile = String(msg.topic || '').split('/');
    if (teile.length < 3 || teile[1] !== 'messwert' || teile[2] === '') {
        return ungueltig('Thema passt nicht zu <präfix>/messwert/<gerät>/<kanal>');
    }
    const geraet = teile[2];
    const kanal = teile.slice(3).join('/') || 'geraet';

    let daten = msg.payload;
    if (Buffer.isBuffer(daten)) {
        daten = daten.toString('utf8');
    }
    if (typeof daten === 'string') {
        try {
            daten = JSON.parse(daten);
        } catch (e) {
            return ungueltig('kein gültiges JSON');
        }
    }
    if (!istObjekt(daten)) {
        return ungueltig('Nutzlast ist kein JSON-Objekt');
    }

    const typ = daten.typ === undefined || daten.typ === null ? undefined : String(daten.typ);

    if (istObjekt(daten.phasen)) {
        for (const phase of Object.keys(daten.phasen)) {
            const werte = daten.phasen[phase];
            if (istObjekt(werte)) {
                punkte.push({ messung: 'strom', tags: { geraet, kanal, phase, typ }, felder: werte, ts: daten.ts, zahlen: true });
            }
        }
    }
    if (istObjekt(daten.zustand)) {
        punkte.push({ messung: 'zustand', tags: { geraet, kanal, typ }, felder: daten.zustand, ts: daten.ts, zahlen: false });
    }
}

const zeilen = [];
for (const p of punkte) {
    const z = zeile(p.messung, p.tags, p.felder, p.ts, p.zahlen);
    if (z !== null) {
        zeilen.push(z);
    }
}

if (zeilen.length === 0) {
    // Leere Punkte werden gar nicht erst geschrieben – das ist kein Fehler,
    // etwa wenn ein Shelly einen Status ohne Messwerte schickt.
    return null;
}

zaehler.zeilen += zeilen.length;
status();
return { zeilen };

/*
 * InfluxDB-Schreiber
 *
 * Sammelt Zeilen und schickt sie gebündelt an den v1-kompatiblen Endpunkt
 *     <INFLUX_URL>/write?db=<INFLUX_DB>&precision=ms
 * Den verstehen InfluxDB 1.8, 2.x (über die DBRP-Zuordnung) und 3.x
 * gleichermaßen – die Flows müssen nicht wissen, welche Fassung läuft.
 *
 * Eingänge (an der Eigenschaft erkennbar):
 *   msg.zeilen      neue Zeilen von „Messwert → Line Protocol"
 *   msg.takt        jede Sekunde: fällige Zeilen abschicken
 *   msg.herzschlag  alle 30 s: eigene Zahlen schreiben und auf MQTT melden
 *   msg.pmStapel    Antwort des http-request-Nodes (oder dessen Fehler über
 *                   den Catch-Node) zu einem abgeschickten Stapel
 *
 * Ausgang 1: Anfrage an den http-request-Node
 * Ausgang 2: Status für pm/status/nodered (retained)
 *
 * Fällt die InfluxDB aus, bleiben die Zeilen bis zu 5 Minuten im Speicher
 * (höchstens 50 000, danach gehen die ältesten verloren und werden gezählt)
 * und werden mit wachsendem Abstand erneut geschickt. Ein Neustart von
 * Node-RED leert den Puffer – dafür ist er nicht gedacht; er überbrückt den
 * Neustart der Datenbank, ein Update oder eine kurze Netzstörung.
 */

const SOFORT_AB = 500;             // so viele Zeilen warten nicht auf den Takt
const STAPEL_MAX = 5000;           // Zeilen je Anfrage
const PUFFER_MAX = 50000;
const ALTER_MAX_MS = 5 * 60 * 1000;
const ANTWORT_FRIST_MS = 30 * 1000;
const WARTEN_MIN_MS = 2000;
const WARTEN_MAX_MS = 30 * 1000;

const z = context.get('schreiber') || {
    bloecke: [],          // [{ t: Eingang in ms, zeilen: [...] }] – älteste vorn
    anzahl: 0,            // Zeilen in allen Blöcken
    unterwegs: null,      // { id, bloecke, n, t }
    stapelNr: 0,
    geschrieben: 0,
    fehler: 0,
    verworfen: 0,
    warten: 0,
    naechsterVersuch: 0,
    letzterFehler: null,
    letzterErfolg: null,
    statusText: '',
};
context.set('schreiber', z);
const jetzt = Date.now();

function verwerfen(n, grund) {
    if (n <= 0) {
        return;
    }
    z.verworfen += n;
    node.warn(n + ' Zeilen verworfen: ' + grund);
}

// Zu alte und überzählige Zeilen entfernen – immer die ältesten zuerst.
function aufraeumen() {
    let zuAlt = 0;
    while (z.bloecke.length > 0 && jetzt - z.bloecke[0].t > ALTER_MAX_MS) {
        zuAlt += z.bloecke[0].zeilen.length;
        z.anzahl -= z.bloecke[0].zeilen.length;
        z.bloecke.shift();
    }
    verwerfen(zuAlt, 'älter als 5 Minuten, InfluxDB nicht erreichbar');

    let zuViel = 0;
    while (z.anzahl > PUFFER_MAX && z.bloecke.length > 0) {
        const block = z.bloecke[0];
        const weg = Math.min(block.zeilen.length, z.anzahl - PUFFER_MAX);
        block.zeilen.splice(0, weg);
        z.anzahl -= weg;
        zuViel += weg;
        if (block.zeilen.length === 0) {
            z.bloecke.shift();
        }
    }
    verwerfen(zuViel, 'Puffer voll (' + PUFFER_MAX + ' Zeilen)');
}

function adresse() {
    const basis = String(env.get('INFLUX_URL') || 'http://127.0.0.1:8086').replace(/\/+$/, '');
    let url = basis + '/write?db=' + encodeURIComponent(env.get('INFLUX_DB') || 'strom') + '&precision=ms';
    const kopf = { 'Content-Type': 'text/plain; charset=utf-8' };
    const token = env.get('INFLUX_TOKEN');
    if (token) {
        // 2.x/3.x: API-Token. 1.8 versteht hier auch „benutzer:kennwort".
        kopf.Authorization = 'Token ' + token;
    } else if (env.get('INFLUX_USER')) {
        url += '&u=' + encodeURIComponent(env.get('INFLUX_USER')) + '&p=' + encodeURIComponent(env.get('INFLUX_PASSWORD') || '');
    }
    return { url, kopf };
}

// Nächsten Stapel abschicken, wenn nichts unterwegs ist und keine Pause läuft.
function senden() {
    if (z.unterwegs) {
        if (jetzt - z.unterwegs.t < ANTWORT_FRIST_MS) {
            return null;
        }
        // Keine Antwort in der Frist – als Fehler werten, Zeilen zurücklegen.
        fehlschlag('keine Antwort nach ' + (ANTWORT_FRIST_MS / 1000) + ' s', true);
    }
    if (z.anzahl === 0 || jetzt < z.naechsterVersuch) {
        return null;
    }

    const bloecke = [];
    const zeilen = [];
    while (z.bloecke.length > 0 && zeilen.length < STAPEL_MAX) {
        const block = z.bloecke[0];
        const platz = STAPEL_MAX - zeilen.length;
        if (block.zeilen.length <= platz) {
            z.bloecke.shift();
            bloecke.push(block);
            for (const zeile of block.zeilen) {
                zeilen.push(zeile);
            }
        } else {
            const teil = { t: block.t, zeilen: block.zeilen.splice(0, platz) };
            bloecke.push(teil);
            for (const zeile of teil.zeilen) {
                zeilen.push(zeile);
            }
        }
    }
    z.anzahl -= zeilen.length;
    z.stapelNr++;
    z.unterwegs = { id: z.stapelNr, bloecke, n: zeilen.length, t: jetzt };

    // Die Methode (POST) steht im http-request-Node selbst; msg.method
    // brächte dort bei jeder Anfrage eine Warnung.
    const ziel = adresse();
    return {
        url: ziel.url,
        headers: ziel.kopf,
        payload: zeilen.join('\n'),
        requestTimeout: 15000,
        pmStapel: z.stapelNr,
    };
}

// Stapel ist nicht angekommen: Zeilen wieder vorn einreihen (mit ihrem
// ursprünglichen Eingangszeitpunkt, damit die 5-Minuten-Grenze gilt) und
// mit wachsendem Abstand erneut versuchen.
function fehlschlag(grund, zuruecklegen) {
    const u = z.unterwegs;
    z.unterwegs = null;
    z.fehler++;
    z.letzterFehler = grund;
    if (u && zuruecklegen) {
        z.bloecke = u.bloecke.concat(z.bloecke);
        z.anzahl += u.n;
        z.warten = Math.min(WARTEN_MAX_MS, Math.max(WARTEN_MIN_MS, z.warten * 2));
        z.naechsterVersuch = jetzt + z.warten;
        aufraeumen();
    } else if (u) {
        verwerfen(u.n, grund);
    }
}

function statusZeigen() {
    let text;
    let farbe;
    if (z.letzterFehler) {
        farbe = 'red';
        text = 'Fehler: ' + String(z.letzterFehler).slice(0, 60) + ' – Puffer ' + z.anzahl;
    } else {
        farbe = 'green';
        text = z.geschrieben + ' geschrieben' + (z.verworfen > 0 ? ', ' + z.verworfen + ' verworfen' : '') + ', Puffer ' + z.anzahl;
    }
    if (text !== z.statusText) {
        z.statusText = text;
        node.status({ fill: farbe, shape: farbe === 'green' ? 'dot' : 'ring', text });
    }
}

let anfrage = null;
let meldung = null;

if (msg.pmStapel !== undefined) {
    // ------------------------------------------------ Antwort der InfluxDB
    // Ein Verbindungsfehler kommt doppelt an (Ausgang und Catch) – es zählt
    // nur die erste Antwort zu dem Stapel, der gerade unterwegs ist.
    if (!z.unterwegs || msg.pmStapel !== z.unterwegs.id) {
        return null;
    }
    const code = msg.statusCode;
    const ok = !msg.error && typeof code === 'number' && code >= 200 && code < 300;
    if (ok) {
        z.geschrieben += z.unterwegs.n;
        z.unterwegs = null;
        z.letzterErfolg = jetzt;
        z.letzterFehler = null;
        z.warten = 0;
        z.naechsterVersuch = 0;
        if (z.anzahl >= SOFORT_AB) {
            anfrage = senden();
        }
    } else {
        const text = msg.error ? String(msg.error.message || msg.error) : String(msg.payload || '').slice(0, 300);
        const grund = (typeof code === 'number' ? 'HTTP ' + code : String(code || 'Verbindungsfehler')) + (text ? ': ' + text : '');
        if (code === 400 || code === 422) {
            // Die Datenbank lehnt den Inhalt ab (Syntax, Feldtyp-Konflikt).
            // Nochmals schicken ändert daran nichts und hielte nur alle
            // anderen Zeilen fünf Minuten lang auf. Bei einem Feldtyp-
            // Konflikt („partial write … dropped=1") hat InfluxDB die übrigen
            // Zeilen geschrieben – dann nur die abgelehnten als verworfen
            // zählen.
            node.warn('InfluxDB lehnt Zeilen ab – ' + grund);
            const abgelehnt = /dropped=(\d+)/.exec(text);
            if (abgelehnt && Number(abgelehnt[1]) <= z.unterwegs.n) {
                z.geschrieben += z.unterwegs.n - Number(abgelehnt[1]);
                z.unterwegs.n = Number(abgelehnt[1]);
            }
            fehlschlag(grund, false);
        } else {
            // Nicht erreichbar, Anmeldung falsch, Datenbank fehlt, 5xx …
            // – Zeilen behalten und später erneut versuchen.
            fehlschlag(grund, true);
        }
    }
    statusZeigen();
} else if (Array.isArray(msg.zeilen)) {
    // ------------------------------------------------ neue Zeilen
    if (msg.zeilen.length > 0) {
        z.bloecke.push({ t: jetzt, zeilen: msg.zeilen.slice() });
        z.anzahl += msg.zeilen.length;
        if (z.anzahl > PUFFER_MAX) {
            aufraeumen();
        }
        if (z.anzahl >= SOFORT_AB) {
            anfrage = senden();
        }
    }
} else if (msg.herzschlag) {
    // ------------------------------------------------ Herzschlag
    // Kommt über denselben Weg in die Datenbank wie alles andere – bleibt
    // er aus, stimmt etwas mit Node-RED oder dem Schreiben nicht.
    // Die Zahlen gelten für den Moment vor dieser Zeile – in Datenbank und
    // MQTT-Meldung dieselben.
    const zahlen = { geschrieben: z.geschrieben, fehler: z.fehler, puffer: z.anzahl, verworfen: z.verworfen };
    const werte = Object.keys(zahlen).map((k) => k + '=' + zahlen[k]).join(',');
    z.bloecke.push({ t: jetzt, zeilen: ['pipeline,quelle=nodered ' + werte + ' ' + jetzt] });
    z.anzahl += 1;
    aufraeumen();
    meldung = {
        topic: 'pm/status/nodered',
        retain: true,
        qos: 1,
        payload: JSON.stringify(Object.assign({ ts: jetzt }, zahlen, {
            letzter_erfolg: z.letzterErfolg,
            letzter_fehler: z.letzterFehler,
        })),
    };
} else if (msg.takt) {
    // ------------------------------------------------ Takt
    aufraeumen();
    anfrage = senden();
    statusZeigen();
}

if (!anfrage && !meldung) {
    return null;
}
return [anfrage, meldung];
